def play_tic_tac_toe():
    # Initialize the board as a 2D list of empty strings
    board = [[" " for _ in range(3)] for _ in range(3)]

    def print_board():
        for row in board:
            print("|".join(row))
            print("-" * 9)

    def get_user_move():
        while True:
            move = input("Enter your move (e.g. 5): ")
            if all(char.isdigit() for char in move) and 1 <= int(move) <= 9:
                row, col = divmod(int(move) - 1, 3)
                return row, col
            else:
                print("Invalid move. Please enter a number between 1 and 9.")

    def update_board(row, col):
        if board[row][col] != " ":
            print("This cell is already occupied. Please choose another one.")
            return
        board[row][col] = "X"

    def check_winner():
        for row in board:
            if row[0] == row[1] == row[2] != " ":
                return row[0]
        for col in zip(*board):
            if col[0] == col[1] == col[2] != " ":
                return col[0]
        if board[0][0] == board[1][1] == board[2][2] != " ":
            return board[0][0]
        if board[0][2] == board[1][1] == board[2][0] != " ":
            return board[0][2]
        return None

    while True:
        print_board()
        row, col = get_user_move()
        update_board(row, col)
        print_board()
        winner = check_winner()
        if winner:
            print(f"Congratulations, player {winner} wins the game!")
            break
        elif " " not in "".join("".join(row) for row in board):
